const assert = require('node:assert/strict');

const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

// tenant filter, limit and validation (existing behavior)
const handler = new OrderHandler(new OrderRepository([
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 }
]));

assert.deepEqual(handler.list({ tenant: 'a', limit: 1 }).items.map(x => x.id), ['a']);
assert.throws(() => handler.list({ tenant: 'a', limit: 0 }), /invalid request/);

// without a cursor the limit still applies, and a further match yields a cursor
assert.equal(handler.list({ tenant: 'a', limit: 1 }).nextCursor, '2026-01-01|a');
// when everything fits on one page the cursor is null
assert.deepEqual(handler.list({ tenant: 'a', limit: 2 }), {
  items: [
    { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
    { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 }
  ],
  nextCursor: null
});
// resuming strictly after a pair, by (createdAt, id) key comparison
assert.deepEqual(handler.list({ tenant: 'a', limit: 2, cursor: '2026-01-01|a' }).items.map(x => x.id), ['b']);
// a cursor pair that belongs to another tenant still just positions the window
assert.deepEqual(handler.list({ tenant: 'a', limit: 2, cursor: '2026-01-01|x' }).items.map(x => x.id), ['b']);
// a cursor resumes even after its row has been deleted
const pruned = new OrderHandler(new OrderRepository([
  { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
  { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 }
]));
assert.deepEqual(pruned.list({ tenant: 'a', limit: 2, cursor: '2026-01-01|a' }).items.map(x => x.id), ['b']);

// full pagination walk: equal-date orders never repeat or get skipped
const seed = [
  { id: 'a5', tenant: 'a', createdAt: '2026-01-03', total: 5 },
  { id: 'b1', tenant: 'b', createdAt: '2026-01-01', total: 6 },
  { id: 'a1', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'b2', tenant: 'b', createdAt: '2026-01-02', total: 7 },
  { id: 'a3', tenant: 'a', createdAt: '2026-01-02', total: 3 },
  { id: 'a2', tenant: 'a', createdAt: '2026-01-01', total: 2 },
  { id: 'a4', tenant: 'a', createdAt: '2026-01-02', total: 4 }
];

function makeFixture() {
  const rows = JSON.parse(JSON.stringify(seed)); // deep copy so mutation can be detected
  return { rows, handler: new OrderHandler(new OrderRepository(rows)) };
}

{
  const { handler: paged, rows } = makeFixture();
  const before = JSON.parse(JSON.stringify(rows));
  const seen = [];
  let cursor;
  for (let page = 0; page < 10; page += 1) {
    const result = cursor === undefined
      ? paged.list({ tenant: 'a', limit: 2 })
      : paged.list({ tenant: 'a', limit: 2, cursor });
    assert.ok(result.items.every(x => x.tenant === 'a'));
    seen.push(...result.items.map(x => x.id));
    cursor = result.nextCursor;
    if (cursor === null) break;
  }
  assert.deepEqual(seen, ['a1', 'a2', 'a3', 'a4', 'a5']);
  assert.deepEqual(rows, before); // input array and rows are untouched
}

{
  const { handler: paged } = makeFixture();
  // last page holds fewer matching orders than the limit
  assert.deepEqual(paged.list({ tenant: 'a', limit: 2, cursor: '2026-01-02|a4' }), {
    items: [{ id: 'a5', tenant: 'a', createdAt: '2026-01-03', total: 5 }],
    nextCursor: null
  });
  // page that ends exactly on the final matching order
  assert.deepEqual(paged.list({ tenant: 'a', limit: 3, cursor: '2026-01-01|a2' }), {
    items: [
      { id: 'a3', tenant: 'a', createdAt: '2026-01-02', total: 3 },
      { id: 'a4', tenant: 'a', createdAt: '2026-01-02', total: 4 },
      { id: 'a5', tenant: 'a', createdAt: '2026-01-03', total: 5 }
    ],
    nextCursor: null
  });
  // foreign-tenant cursor pair: filtering precedes pagination
  assert.deepEqual(paged.list({ tenant: 'a', limit: 1, cursor: '2026-01-01|b1' }).items.map(x => x.id), ['a3']);
  // other tenants are unaffected
  assert.deepEqual(paged.list({ tenant: 'b', limit: 10 }), {
    items: [
      { id: 'b1', tenant: 'b', createdAt: '2026-01-01', total: 6 },
      { id: 'b2', tenant: 'b', createdAt: '2026-01-02', total: 7 }
    ],
    nextCursor: null
  });
}

// invalid requests: empty tenant, bad limit, malformed cursor
{
  const { handler: paged } = makeFixture();
  const bad = [
    { tenant: '', limit: 1 },
    { tenant: 'a', limit: 0 },
    { tenant: 'a', limit: 101 },
    { tenant: 'a', limit: 1.5 },
    { tenant: 'a', limit: NaN },
    { tenant: 'a', limit: 1, cursor: '' },
    { tenant: 'a', limit: 1, cursor: 'no-delimiter' },
    { tenant: 'a', limit: 1, cursor: '2026-01-01||a1' },
    { tenant: 'a', limit: 1, cursor: '2026-01-01|' },
    { tenant: 'a', limit: 1, cursor: '|a1' },
    { tenant: 'a', limit: 1, cursor: 5 },
    { tenant: 'a', limit: 1, cursor: null }
  ];
  for (const request of bad) {
    assert.throws(() => paged.list(request), /invalid request/, JSON.stringify(request));
  }
}

// repository exposes the same filtering, ordering and resumption
{
  const { rows } = makeFixture();
  const repository = new OrderRepository(rows);
  assert.deepEqual(repository.list('a').map(x => x.id), ['a1', 'a2', 'a3', 'a4', 'a5']);
  assert.deepEqual(repository.list('a', '2026-01-01|a2').map(x => x.id), ['a3', 'a4', 'a5']);
  assert.throws(() => repository.list('a', 'bogus'), /invalid request/);
}

console.log('public checks passed');

