import { Order } from './types';

const CURSOR_SEPARATOR = '|';

interface OrderKey {
  readonly createdAt: string;
  readonly id: string;
}

function compareOrders(a: OrderKey, b: OrderKey): number {
  if (a.createdAt < b.createdAt) return -1;
  if (a.createdAt > b.createdAt) return 1;
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

export function formatCursor(order: OrderKey): string {
  return order.createdAt + CURSOR_SEPARATOR + order.id;
}

export function parseCursor(cursor: string): OrderKey {
  if (typeof cursor !== 'string') {
    throw new Error('invalid request');
  }
  const parts = cursor.split(CURSOR_SEPARATOR);
  if (parts.length !== 2 || !parts[0] || !parts[1]) {
    throw new Error('invalid request');
  }
  return { createdAt: parts[0], id: parts[1] };
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  list(tenant: string, cursor?: string): Order[] {
    const after = cursor === undefined ? null : parseCursor(cursor);
    const matching = this.rows.filter(row => row.tenant === tenant);
    matching.sort(compareOrders);
    if (after === null) {
      return matching;
    }
    return matching.filter(row => compareOrders(row, after) > 0);
  }
}
